-- Merck Spectroquant® thermoreactors TR 320 / 420 / 620 and Move 100 portable colorimeter, with accessories (9 products).
-- Run once in Supabase -> SQL Editor (choose "Run without RLS" if asked). Safe to run again.
alter table products add column if not exists features jsonb not null default '[]'::jsonb;
insert into brands (name, slug, website_url) values ('Merck', 'merck', 'https://www.sigmaaldrich.com/') on conflict (slug) do nothing;
insert into categories (name, slug, sort_order) values ('Environmental Equipment', 'environmental-equipment', 6) on conflict (slug) do nothing;

insert into products (sku, name, slug, description, specs, features, category_id, brand_id, image_url, is_active)
select v.sku, v.name, v.slug, v.description, v.specs::jsonb, v.features::jsonb, c.id, b.id, v.image_url, true
from (values
  ('MERCK-1.71200.0001', 'Merck Spectroquant® TR 320 Thermoreactor', 'merck-spectroquant-tr-320-thermoreactor', 'Spectroquant® TR 320 is the standard thermoreactor for basic use: a 12-hole heating block for 16 mm cell tests with 8 pre-installed digestion programs (COD, TOC, nitrogen, metals, phosphorus), for reliable, error-free sample preparation.', '[["Model", "Spectroquant® TR 320"], ["Catalogue No.", "1.71200.0001"], ["Holes", "12 for 16 mm cell tests"], ["Temperature selection", "100, 120, 148 and 150 °C ±1.0 °C"], ["Scope of delivery", "Integrated protective hood; for COD, TOC and total contents of Cd, Cr, Cu, CN, Fe, Pb, Ni, N, P, Ag and Zn"], ["Display", "LCD showing set and actual temperature and heating time"], ["Heater", "LED status (blinks while heating, steady during digestion); contact guard on heating block"], ["Pre-installed programs", "8: 148 °C (20 or 120 min), 150 °C (120 min), 120 °C (30, 60 or 120 min), 100 °C (30 or 60 min); automatic switch-off"], ["Controlling accuracy", "±1 °C ±1 digit"], ["Mains", "115 V~ / 230 V~, 50 / 60 Hz convertible"], ["Dimensions (H × W × D)", "180 × 245 × 292 mm"], ["Weight", "2.85 kg"]]', '["8 pre-installed digestion programs for COD, TOC, total nitrogen, metals, AOX, phosphorus and cyanide", "Integrated protective hood for safe digestion", "Automatic power switch-off at the end of the heating time", "Clear LCD with set and actual temperature and time"]', '/products/merck/tr-320.jpg'),
  ('MERCK-1.71201.0001', 'Merck Spectroquant® TR 420 Thermoreactor', 'merck-spectroquant-tr-420-thermoreactor', 'Spectroquant® TR 420 is the advanced thermoreactor for frequent use: 24 holes for 16 mm cell tests, 8 pre-installed plus 8 freely selectable programs, free temperature (room temperature to 170 °C) and timer selection, and AQA documentation with the optional thermosensor.', '[["Model", "Spectroquant® TR 420"], ["Catalogue No.", "1.71201.0001"], ["Holes", "24 for 16 mm cell tests"], ["Programs", "8 pre-installed + 8 freely selectable"], ["Temperature selection", "100, 120, 148 and 150 °C, or freely from room temperature to 170 °C (±1.0 °C)"], ["Timer", "0 – 180 min freely selectable"], ["Scope of delivery", "Integrated protective hood; for COD, TOC and total contents of Cd, Cr, Cu, CN, Fe, Pb, Ni, N, P, Ag and Zn"], ["Display", "LCD showing set and actual temperature and heating time"], ["Heater", "LED status (blinks while heating, steady during digestion); contact guard on heating block"], ["Pre-installed programs", "8: 148 °C (20 or 120 min), 150 °C (120 min), 120 °C (30, 60 or 120 min), 100 °C (30 or 60 min); automatic switch-off"], ["Controlling accuracy", "±1 °C ±1 digit"], ["Mains", "115 V~ / 230 V~, 50 / 60 Hz convertible"], ["Dimensions (H × W × D)", "180 × 245 × 292 mm"], ["Weight", "3.6 kg"], ["Optional accessories", "Thermosensor (1.71203.0001) and PC cable (1.71204.0001) for AQA documentation"]]', '["8 pre-installed digestion programs for COD, TOC, total nitrogen, metals, AOX, phosphorus and cyanide", "Integrated protective hood for safe digestion", "Automatic power switch-off at the end of the heating time", "Clear LCD with set and actual temperature and time", "24 samples digested at once", "Free temperature and time programming"]', '/products/merck/tr-420.jpg'),
  ('MERCK-1.71202.0001', 'Merck Spectroquant® TR 620 Thermoreactor', 'merck-spectroquant-tr-620-thermoreactor', 'Spectroquant® TR 620 is a two-in-one thermoreactor for flexible use: 2 × 12 holes with two separately controlled heating zones, so two different digestions can run at the same time, with 8 pre-installed and 8 freely selectable programs.', '[["Model", "Spectroquant® TR 620"], ["Catalogue No.", "1.71202.0001"], ["Holes", "24 (2 × 12) for 16 mm cell tests"], ["Heating zones", "2, separately temperature-controlled"], ["Programs", "8 pre-installed + 8 freely selectable"], ["Temperature selection", "100, 120, 148 and 150 °C, or freely from room temperature to 170 °C (±1.0 °C)"], ["Timer", "0 – 180 min freely selectable"], ["Scope of delivery", "Integrated protective hood; for COD, TOC and total contents of Cd, Cr, Cu, CN, Fe, Pb, Ni, N, P, Ag and Zn"], ["Display", "LCD showing set and actual temperature and heating time"], ["Heater", "LED status (blinks while heating, steady during digestion); contact guard on heating block"], ["Pre-installed programs", "8: 148 °C (20 or 120 min), 150 °C (120 min), 120 °C (30, 60 or 120 min), 100 °C (30 or 60 min); automatic switch-off"], ["Controlling accuracy", "±1 °C ±1 digit"], ["Mains", "115 V~ / 230 V~, 50 / 60 Hz convertible"], ["Dimensions (H × W × D)", "180 × 245 × 292 mm"], ["Weight", "3.6 kg"], ["Optional accessories", "Thermosensor (1.71203.0001) and PC cable (1.71204.0001) for AQA documentation"]]', '["8 pre-installed digestion programs for COD, TOC, total nitrogen, metals, AOX, phosphorus and cyanide", "Integrated protective hood for safe digestion", "Automatic power switch-off at the end of the heating time", "Clear LCD with set and actual temperature and time", "Two temperature zones in one instrument", "Free temperature and time programming"]', '/products/merck/tr-620.jpg'),
  ('MERCK-1.71203.0001', 'Merck Spectroquant® Thermosensor for TR 420 / TR 620', 'merck-spectroquant-thermosensor-tr-420-620', 'Thermosensor for Spectroquant® thermoreactors TR 420 and TR 620. It measures the actual temperature in the bore of the heating block and compares it with the set temperature; results can be sent to a PC for AQA documentation.', '[["Catalogue No.", "1.71203.0001"], ["Compatible with", "Spectroquant® TR 420, TR 620"], ["Design", "Brass adapter with integrated Pt sensor fitting the 16 mm holes, incl. connector cable"], ["Use", "Heating-block temperature monitoring and documentation for AQA"]]', '[]', null),
  ('MERCK-1.71204.0001', 'Merck Spectroquant® PC Cable for TR 420 / TR 620', 'merck-spectroquant-pc-cable-tr-420-620', 'PC cable for Spectroquant® thermoreactors TR 420 and TR 620, used with the thermosensor to transfer temperature records to a PC for documentation.', '[["Catalogue No.", "1.71204.0001"], ["Compatible with", "Spectroquant® TR 420, TR 620"]]', '[]', null),
  ('MERCK-1.73632.0001', 'Merck Spectroquant® Move 100 Portable Colorimeter', 'merck-spectroquant-move-100-portable-colorimeter', 'Spectroquant® Move 100 is a small, rugged portable colorimeter for rapid on-site drinking water and wastewater analysis. It covers every important parameter in one instrument, with over 100 pre-programmed and 35 user-defined methods, so samples are measured on the spot without delay or deterioration.', '[["Model", "Spectroquant® Move 100"], ["Catalogue No.", "1.73632.0001"], ["Type", "Portable colorimeter"], ["Methods", "Over 100 pre-programmed and 35 user-defined methods"], ["Display", "Backlit graphic display"], ["Interfaces", "IR interface for data transfer; RJ45 connector for software updates"], ["Optics", "LED, interference filter, photosensor, transparent measurement chamber"], ["Wavelengths", "430, 530, 560, 580, 610 and 660 nm"], ["Wavelength accuracy", "±1 nm"], ["Photometric accuracy", "1.000 Abs ±0.020 Abs; 2.600 Abs ±0.052 Abs (2% FS, standard solutions at 20 – 25 °C)"], ["Photometric resolution", "0.005 A"], ["Operation", "Acid and solvent resistant tactile film keyboard"], ["Power supply", "4 × AA batteries; approx. 26 hours continuous use or 3,500 tests"], ["IP classification", "IP 68, dust tight and waterproof"], ["Storage capacity", "approx. 1,000 data sets"], ["Weight", "approx. 450 g"], ["Dimensions", "approx. 210 × 95 × 45 mm (instrument); 395 × 295 × 106 mm (case)"], ["Scope of delivery", "Instrument in carrying case, 4 batteries, 3 round vials each 24 and 16 mm, 16 mm vial adapter, screwdriver, guarantee and compliance certificates, manual"]]', '["Over 100 pre-programmed methods for drinking and waste water", "IP 68 dust tight and waterproof casing with no moving parts", "Wide choice of measuring ranges for accurate results", "Simplified Analytical Quality Assurance with Spectroquant® test kits and Verification Standard", "Battery powered: about 26 hours or 3,500 tests", "Stores about 1,000 results; IR data transfer to PC or printer"]', '/products/merck/move-100.jpg'),
  ('MERCK-1.73633.0001', 'Merck Spectroquant® Data Transfer for Move 100', 'merck-spectroquant-data-transfer-move-100', 'Spectroquant® Data Transfer uses infrared to transmit or print measurement data from the Spectroquant® Move 100 colorimeter. Results can be saved on a PC as .xls or .txt files, or printed on a USB or serial printer.', '[["Catalogue No.", "1.73633.0001"], ["Compatible with", "Spectroquant® Move 100"], ["Connection", "Infrared from the colorimeter; USB to PC"], ["Export formats", ".xls or .txt"], ["Printing", "USB printer (HP PCL 5 and below) or any ASCII serial printer"], ["Scope of delivery", "Instrument, USB cable, 4 batteries, screwdriver, CD-ROM with software, instructions, guarantee certificate"]]', '[]', '/products/merck/move-100-data-transfer.jpg'),
  ('MERCK-1.19302.0001', 'Merck Spectroquant® Verification Standard for Move 100', 'merck-spectroquant-verification-standard-move-100', 'Spectroquant® Verification Standard for checking the Move 100 colorimeter: sealed cells with stable coloured solutions for measuring absorbance at all six instrument wavelengths, for simple Analytical Quality Assurance.', '[["Catalogue No.", "1.19302.0001"], ["Contents", "6 sealed cells with stable coloured solutions (430, 530, 560, 580, 610 and 660 nm) plus 1 sealed blank cell"], ["Included", "Quality certificate and user instructions"], ["Compatible with", "Spectroquant® Move 100"]]', '[]', '/products/merck/verification-standard.jpg'),
  ('MERCK-1.73634.0001', 'Merck Spectroquant® Update Cable for Move 100', 'merck-spectroquant-update-cable-move-100', 'Update cable for installing the latest software on the Spectroquant® Move 100 colorimeter.', '[["Catalogue No.", "1.73634.0001"], ["Compatible with", "Spectroquant® Move 100"]]', '[]', null)
) as v(sku, name, slug, description, specs, features, image_url)
cross join (select id from categories where slug = 'environmental-equipment') c
cross join (select id from brands where slug = 'merck') b
on conflict (sku) do update set name = excluded.name, slug = excluded.slug, description = excluded.description, specs = excluded.specs,
  features = excluded.features, category_id = excluded.category_id, brand_id = excluded.brand_id, image_url = excluded.image_url, is_active = true;

select name, sku from products where sku in ('MERCK-1.71200.0001', 'MERCK-1.71201.0001', 'MERCK-1.71202.0001', 'MERCK-1.71203.0001', 'MERCK-1.71204.0001', 'MERCK-1.73632.0001', 'MERCK-1.73633.0001', 'MERCK-1.19302.0001', 'MERCK-1.73634.0001') order by sku;
